
public class typeconversion_casting {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		
		byte b = 127;
		System.out.println(b); 
		int a =12;
		b=(byte)a;
		System.out.println(b);
		
		float f=5.6f;
		int x=(int)f;
		System.out.print(x);
		
	}

}
